syntax:
#define MACRO_NAME(params) replacement_list_with_## 
// Implementation notes: 
// - '##' must be used between two preprocessing tokens; it concatenates them into a single token. 
// - After concatenation, the result is rescanned for macros, but the macro being expanded is not replaced in its own list to avoid recursion. 
// Example: #define CONCAT(a, b) a ## b  // Concatenates 'a' and 'b' into a single token, e.g., CONCAT(foo, bar) becomes 'foobar' after preprocessing.

code_example:
#include <iostream>

#define CONCAT(a, b) a ## b
#define NUMBER 123

int main() {
    int value = CONCAT(NUMBER, 456);  // Preprocessor concatenates to '123456'
    std::cout << value << std::endl;  // Outputs: 123456
    return 0;
}
